def specialFilter(nums):
    count = 0
    for num in nums:
        if num > 10:
            first_digit = int(str(abs(num))[0])
            last_digit = int(str(abs(num))[-1])
            if first_digit in [1, 3, 5, 7, 9] and last_digit in [1, 3, 5, 7, 9]:
